test:
permissions = PagePermissions()
permissions.add_page('root')
assert permissions.getUserPermissionForPage('root', 'nobody') == 'none'
for call in (lambda: permissions.add_page('child', 'missing'), lambda: permissions.grant_user('missing', 'ada', 'view'), lambda: permissions.grant_user('root', 'ada', 'owner')):
    try:
        call()
        raise AssertionError('expected ValueError')
    except ValueError:
        pass
